<section class="hero"><div class="container"><div class="hero-grid"><?php $q=new WP_Query(['posts_per_page'=>4]); while($q->have_posts()):$q->the_post(); ?><article class="news-card"><?php if(has_post_thumbnail()) the_post_thumbnail('large'); ?><div class="card-body"><span><?php the_category(', '); ?></span><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),18)); ?></p></div></article><?php endwhile; wp_reset_postdata(); ?></div></div></section>